//! Kani proof harnesses: bounded proofs of the core pure functions, over
//! every value of the inputs at each listed size (not samples). Run with
//! `cargo kani -p betula`.
//!
//! Sizes are concrete per harness (generated by macros) and contents are
//! symbolic: symbolic lengths make CBMC's formulas blow up.

use std::ops::Bound;

use crate::hlc::Hlc;
use crate::node::{
    child_bounds, child_index, chunk_by_bytes, first_child, group_starts, last_child, merge_newest,
};
use crate::segments::{CleanerConfig, SegmentTable, SegmentUsage, account, pick_victims};
use crate::tree::splice_children;
use crate::types::{Epoch, NodePtr, SegmentId};

/// A strictly key-sorted run of (key, stamp), as buffers and leaves are.
fn sorted_run(len: usize) -> Vec<(u8, u8)> {
    let mut v: Vec<(u8, u8)> = Vec::with_capacity(len);
    for i in 0..len {
        let k: u8 = kani::any();
        kani::assume(k < 4);
        if i > 0 {
            kani::assume(k > v[i - 1].0);
        }
        v.push((k, kani::any()));
    }
    v
}

fn contains(run: &[(u8, u8)], e: (u8, u8)) -> bool {
    let mut i = 0;
    while i < run.len() {
        if run[i] == e {
            return true;
        }
        i += 1;
    }
    false
}

fn stamp(s: &u8) -> u8 {
    *s
}

/// Sorted, each input key exactly once with its newest stamp, nothing
/// invented.
fn check_merge_keeps_newest(la: usize, lb: usize) {
    let a = sorted_run(la);
    let b = sorted_run(lb);
    let out = merge_newest(a.clone(), b.clone(), stamp);
    for i in 1..out.len() {
        assert!(out[i - 1].0 < out[i].0);
    }
    for (k, s) in a.iter().chain(b.iter()) {
        let mut found = false;
        for (ok, os) in &out {
            if ok == k {
                assert!(os >= s);
                found = true;
            }
        }
        assert!(found);
    }
    for e in &out {
        assert!(contains(&a, *e) || contains(&b, *e));
    }
}

/// With unique timestamps (as hybrid timestamps are), the order of
/// application doesn't matter.
fn check_merge_commutes(la: usize, lb: usize) {
    let a = sorted_run(la);
    let b = sorted_run(lb);
    for (ka, sa) in &a {
        for (kb, sb) in &b {
            kani::assume(ka != kb || sa != sb);
        }
    }
    assert!(merge_newest(a.clone(), b.clone(), stamp) == merge_newest(b, a, stamp));
}

/// Neither does the grouping of batches.
fn check_merge_associates(la: usize, lb: usize, lc: usize) {
    let (a, b, c) = (sorted_run(la), sorted_run(lb), sorted_run(lc));
    let left = merge_newest(merge_newest(a.clone(), b.clone(), stamp), c.clone(), stamp);
    let right = merge_newest(a, merge_newest(b, c, stamp), stamp);
    assert!(left == right);
}

macro_rules! harnesses {
    ($check:ident, $unwind:literal: $($name:ident ($($len:literal),*);)*) => {$(
        #[kani::proof]
        #[kani::unwind($unwind)]
        #[kani::solver(cadical)]
        fn $name() {
            $check($($len),*);
        }
    )*};
}

harnesses!(check_merge_keeps_newest, 6:
    merge_newest_1_1(1, 1);
    merge_newest_2_1(2, 1);
    merge_newest_1_2(1, 2);
    merge_newest_2_2(2, 2);
);

harnesses!(check_merge_commutes, 6:
    merge_commutes_1_1(1, 1);
    merge_commutes_2_1(2, 1);
    merge_commutes_2_2(2, 2);
);

harnesses!(check_merge_associates, 6:
    merge_associates_1_1_1(1, 1, 1);
    merge_associates_2_1_1(2, 1, 1);
    merge_associates_1_2_1(1, 2, 1);
);

/// Leaf splitting keeps every entry in order, never yields an empty leaf,
/// and closes a leaf as soon as it reaches the balanced target.
fn check_chunks(len: usize) {
    let mut items: Vec<u8> = Vec::with_capacity(len);
    for _ in 0..len {
        let s: u8 = kani::any();
        kani::assume((1..=3).contains(&s));
        items.push(s);
    }
    let target: usize = kani::any();
    kani::assume((1..=6).contains(&target));
    let size = |s: &u8| *s as usize;
    let chunks = chunk_by_bytes(items.clone(), target, size);
    let mut total = 0;
    for s in &items {
        total += size(s);
    }
    let n = total.div_ceil(target).max(1);
    let per_chunk = total.div_ceil(n);
    let mut at = 0;
    for c in &chunks {
        assert!(!c.is_empty());
        let mut bytes = 0;
        for s in c {
            assert!(at < items.len() && *s == items[at]);
            at += 1;
            bytes += size(s);
        }
        // Before its last item the chunk was still under the target.
        assert!(bytes - size(&c[c.len() - 1]) < per_chunk);
    }
    assert!(at == items.len());
}

harnesses!(check_chunks, 6:
    chunks_1(1);
    chunks_2(2);
    chunks_3(3);
);

/// Internal-node splits: groups start at 0, cover every child, are
/// non-empty and respect the fanout.
#[kani::proof]
#[kani::unwind(10)]
#[kani::solver(cadical)]
fn group_starts_respect_fanout() {
    let n: usize = kani::any();
    let max: usize = kani::any();
    kani::assume((1..=8).contains(&n) && (1..=4).contains(&max));
    let starts = group_starts(n, max);
    assert!(starts.len() == n.div_ceil(max));
    assert!(starts[0] == 0);
    for g in 0..starts.len() {
        let end = if g + 1 < starts.len() {
            starts[g + 1]
        } else {
            n
        };
        assert!(end > starts[g] && end - starts[g] <= max);
    }
}

fn sorted_pivots(len: usize) -> Vec<u8> {
    let mut v: Vec<u8> = Vec::with_capacity(len);
    for i in 0..len {
        let p: u8 = kani::any();
        if i > 0 {
            kani::assume(p > v[i - 1]);
        }
        v.push(p);
    }
    v
}

/// Routing: the child a key is sent to covers that key, and range scans
/// start and stop at the right children.
fn check_routing(len: usize) {
    let pivots = sorted_pivots(len);
    let key: u8 = kani::any();
    let i = child_index::<u8, u8>(&pivots, &key);
    assert!(i <= pivots.len());
    let (lo, hi) = child_bounds(&pivots, i);
    assert!(lo.is_none_or(|lo| *lo <= key));
    assert!(hi.is_none_or(|hi| key < *hi));

    let bound: u8 = kani::any();
    assert!(
        first_child::<u8, u8>(&pivots, &Bound::Included(bound))
            == child_index::<u8, u8>(&pivots, &bound)
    );
    assert!(first_child::<u8, u8>(&pivots, &Bound::Unbounded) == 0);
    assert!(last_child::<u8, u8>(&pivots, &Bound::Unbounded) == pivots.len());
    // Every key below an exclusive end is routed at or before last_child.
    let last = last_child::<u8, u8>(&pivots, &Bound::Excluded(bound));
    if key < bound {
        assert!(i <= last);
    }
    assert!(last <= child_index::<u8, u8>(&pivots, &bound));
}

harnesses!(check_routing, 6:
    routing_0(0);
    routing_1(1);
    routing_2(2);
    routing_3(3);
);

/// Replacing or removing a child keeps `children = pivots + 1` and pivots
/// strictly sorted.
fn check_splice(pivot_count: usize, rest_count: usize) {
    let mut pivots = sorted_pivots(pivot_count);
    let mut children: Vec<u8> = Vec::with_capacity(pivot_count + 1);
    for _ in 0..=pivot_count {
        children.push(kani::any());
    }
    let i: usize = kani::any();
    kani::assume(i < children.len());
    let replacement = if kani::any() {
        None
    } else {
        // New pivots sit strictly inside child i's range.
        let lows = sorted_pivots(rest_count);
        for l in &lows {
            kani::assume(i == 0 || *l > pivots[i - 1]);
            kani::assume(i >= pivots.len() || *l < pivots[i]);
        }
        let mut rest: Vec<(u8, u8)> = Vec::with_capacity(rest_count);
        for l in lows {
            rest.push((l, kani::any()));
        }
        Some((kani::any::<u8>(), rest))
    };
    splice_children(&mut pivots, &mut children, i, replacement);
    if !children.is_empty() {
        assert!(children.len() == pivots.len() + 1);
    }
    for j in 1..pivots.len() {
        assert!(pivots[j - 1] < pivots[j]);
    }
}

harnesses!(check_splice, 6:
    splice_0_0(0, 0);
    splice_1_1(1, 1);
    splice_2_1(2, 1);
    splice_1_2(1, 2);
    splice_2_2(2, 2);
);

/// The hybrid clock never repeats or goes back, even when physical time
/// does, and orders after anything it observed. (Single-threaded, its
/// compare-and-swap retry loop succeeds on the first try, so unwind 3 is
/// exact.)
#[kani::proof]
#[kani::unwind(3)]
fn hlc_is_strictly_monotonic() {
    let c = Hlc::default();
    let (a, b, d): (u64, u64, u64) = (kani::any(), kani::any(), kani::any());
    kani::assume(a < 1 << 40 && b < 1 << 40 && d < 1 << 40);
    let t1 = c.now(a);
    let t2 = c.now(b);
    assert!(t2 > t1);
    let seen: u64 = kani::any();
    kani::assume(seen < 1 << 60);
    c.observe(seen);
    let t3 = c.now(d);
    assert!(t3 > seen && t3 > t2);
}

fn seg(seq: u64) -> SegmentId {
    SegmentId {
        epoch: Epoch(1),
        seq,
    }
}

fn ptr(s: u64, len: u8) -> NodePtr {
    NodePtr {
        seg: seg(s),
        offset: 0,
        len: len.into(),
    }
}

/// Space accounting: live bytes drop by exactly what was freed, a new
/// segment starts fully live, and a segment is reported dead (and dropped
/// from the table) exactly when nothing in it is live.
#[kani::proof]
#[kani::unwind(4)]
#[kani::solver(cadical)]
fn account_tracks_live_bytes() {
    let live0: u8 = kani::any();
    kani::assume(live0 > 0);
    let mut prev = SegmentTable::new();
    prev.insert(
        seg(0),
        SegmentUsage {
            total: 255,
            live: live0.into(),
        },
    );
    let new_total: u8 = kani::any();
    kani::assume(new_total > 0);
    // One freed node in the old segment, one in the new one.
    let (f0, f1): (u8, u8) = (kani::any(), kani::any());
    kani::assume(f0 > 0 && f0 <= live0 && f1 > 0 && f1 <= new_total);
    let freed = [ptr(0, f0), ptr(1, f1)];
    let (table, dead) = account(&prev, &[(seg(1), new_total.into())], &freed);
    let check = |s: u64, left: u8| match table.get(&seg(s)) {
        Some(u) => assert!(u.live == u64::from(left) && left > 0 && !dead.contains(&seg(s))),
        None => assert!(left == 0 && dead.contains(&seg(s))),
    };
    check(0, live0 - f0);
    check(1, new_total - f1);
}

/// The cleaner only picks segments under the live threshold, and moves at
/// most its budget unless a single victim alone exceeds it.
#[kani::proof]
#[kani::unwind(4)]
#[kani::solver(cadical)]
fn victims_respect_threshold_and_budget() {
    let mut table = SegmentTable::new();
    for s in 0..2u64 {
        let live: u8 = kani::any();
        kani::assume(live > 0 && live <= 100);
        table.insert(
            seg(s),
            SegmentUsage {
                total: 100,
                live: live.into(),
            },
        );
    }
    let budget: u8 = kani::any();
    let cfg = CleanerConfig {
        clean_below_live: 0.5,
        max_moved_bytes: budget.into(),
    };
    let victims = pick_victims(&table, &cfg);
    let mut moved = 0u64;
    for id in &victims {
        let u = table[id];
        assert!(u.live < 50);
        moved += u.live;
    }
    assert!(victims.len() <= 1 || moved <= u64::from(budget));
}
